static inline int get_recursion_context(u8 *recursion)
{
	unsigned char rctx = interrupt_context_level();

	if (recursion[rctx])
		return -1;

	recursion[rctx]++;
	barrier();

	return rctx;
}

static inline void put_recursion_context(u8 *recursion, unsigned char rctx)
{
	barrier();
	recursion[rctx]--;
}

