	rv_detach_trace_probe("sco", sched_set_state_tp, handle_sched_set_state);
	rv_detach_trace_probe("sco", sched_entry_tp, handle_schedule_entry);
	rv_detach_trace_probe("sco", sched_exit_tp, handle_schedule_exit);

	da_monitor_destroy();
}

