void __init trace_append_boot_param(char *buf, const char *str, char sep,
				    int size)
{
	int len, needed, str_len;

	if (!*str)
		return;

	len = strlen(buf);
	str_len = strlen(str);
	needed = len + str_len + 1;

	/* For continuation, account for the separator. */
	if (len)
		needed++;
	if (needed > size)
		return;

	if (len)
		buf[len++] = sep;

	strscpy(buf + len, str, size - len);
}

