	if (unlikely(!trace) || trace->nr < skip) {
		if (may_fault)
			rcu_read_unlock();
		goto err_fault;
	}

	trace_nr = trace->nr - skip;
	copy_len = trace_nr * elem_size;

	ips = trace->ip + skip;
