static struct ftrace_hash *hash_sub(struct ftrace_hash *a, struct ftrace_hash *b)
{
	struct ftrace_func_entry *entry, *del;
	struct ftrace_hash *sub;
	int size;

	sub = alloc_and_copy_ftrace_hash(a->size_bits, a);
	if (!sub)
